	@Test
	void visibleMenuGroupsAndItemsExposeImmutableConfiguredMetadata() {
		Properties properties = new Properties();
		properties.setProperty("menu.items", "query,summary,update,add");
		properties.setProperty("menu.groups", "explore,modify");
		properties.setProperty("menu.group.explore.visible", "true");
		properties.setProperty("menu.group.explore.label", "Explore data");
		properties.setProperty("menu.group.explore.icon", "database");
		properties.setProperty("menu.group.explore.order", "9");
		properties.setProperty("menu.group.modify.visible", "true");
		properties.setProperty("menu.group.modify.label", "Modify data");
		properties.setProperty("menu.group.modify.icon", "edit");
		properties.setProperty("menu.group.modify.order", "2");
		properties.setProperty("menu.item.query.label", "SPARQL query");
		properties.setProperty("menu.item.query.icon", "search");
		properties.setProperty("menu.item.query.order", "4");
		properties.setProperty("menu.item.summary.order", "4");

		WorkbenchPolicy policy = WorkbenchPolicy.fromProperties(properties, Set.of());
		var groups = policy.getVisibleMenuGroups();

		assertThat(groups).extracting(group -> group.getId()).containsExactly("modify", "explore");
		assertThat(groups).extracting(group -> group.getLabel()).containsExactly("Modify data", "Explore data");
		assertThat(groups).extracting(group -> group.getIcon()).containsExactly("edit", "database");
		assertThat(groups).extracting(group -> group.getOrder()).containsExactly(2, 9);
		assertThat(groups.get(1).getItems()).extracting(item -> item.getId()).containsExactly("query", "summary");
		assertThat(groups.get(1).getItems().get(0).getLabel()).isEqualTo("SPARQL query");
		assertThat(groups.get(1).getItems().get(0).getIcon()).isEqualTo("search");
		assertThat(groups.get(1).getItems().get(0).getOrder()).isEqualTo(4);
		assertThat(groups.get(1).getItems().get(0).getHref()).isEqualTo("query");
		assertThatThrownBy(() -> groups.clear()).isInstanceOf(UnsupportedOperationException.class);
		assertThatThrownBy(() -> groups.get(1).getItems().clear())
				.isInstanceOf(UnsupportedOperationException.class);
	}

	@Test
	void explicitPageSettingIntersectsWithMenuVisibilityAndOmittedGroupsDenyChildren() {
		Properties pageDisabled = new Properties();
		pageDisabled.setProperty("menu.items", "summary");
		pageDisabled.setProperty("menu.group.explore.visible", "true");
		pageDisabled.setProperty("page.summary.enabled", "false");
		WorkbenchPolicy disabledPolicy = WorkbenchPolicy.fromProperties(pageDisabled, Set.of());

		assertThat(disabledPolicy.isRouteAllowed("/repositories/example/summary")).isFalse();

		Properties pageEnabledButGroupHidden = new Properties();
		pageEnabledButGroupHidden.setProperty("menu.items", "summary");
		pageEnabledButGroupHidden.setProperty("menu.group.explore.visible", "false");
		pageEnabledButGroupHidden.setProperty("page.summary.enabled", "true");
		WorkbenchPolicy hiddenGroupPolicy = WorkbenchPolicy.fromProperties(pageEnabledButGroupHidden, Set.of());

		assertThat(hiddenGroupPolicy.isRouteAllowed("/repositories/example/summary")).isFalse();

		Properties groupOmitted = new Properties();
		groupOmitted.setProperty("menu.items", "summary");
		WorkbenchPolicy omittedGroupPolicy = WorkbenchPolicy.fromProperties(groupOmitted, Set.of());

		assertThat(omittedGroupPolicy.isRouteAllowed("/repositories/example/summary")).isFalse();
	}

